import { initialState } from '../store/configureStore';
import { fetchAuth } from '../actions/authActions'

import axios from 'axios';

export const COMMENTERS_SEARCH_URL_CHANGE = 'COMMENTERS_SEARCH_URL_CHANGE'
export const COMMENTERS_SEARCH_SUBMIT_ENABLE = 'COMMENTERSSEARCH_SUBMIT_ENABLE'
export const COMMENTERS_SEARCH_SUBMIT_DISABLE = 'COMMENTERSSEARCH_SUBMIT_DISABLE'
export const COMMENTERS_SEARCH_SUBMITTED = 'COMMENTERSSEARCH_SUBMITTED'

export const COMMENTERS_SEARCH_SC_LOGIN_ERROR = 'COMMENTERSSEARCH_SC_LOGIN_ERROR'
export const COMMENTERS_SEARCH_COOKIE_ERROR = 'COMMENTERSSEARCH_COOKIE_ERROR'
export const COMMENTERS_SEARCH_USER_CREATED_ERROR = 'COMMENTERSSEARCH_USER_CREATED_ERROR'
export const COMMENTER_SSEARCH_SUCCESS = 'COMMENTERSSEARCH_SUCCESS'


export function handleCommentersSearchChange(event) {
    
    return (dispatch, getState) => {
        
        const { name, value } = event.target
        
        if (name === 'scUsername') {
            dispatch({
                type: COMMENTERSSEARCH_USERNAME_CHANGE,
                scUsername: value
            })
        } else  if (name === 'scPassword') {
            dispatch({
                type: COMMENTERSSEARCH_PASSWORD_CHANGE,
                scPassword: value
            })
        }
        
        if(getState().scUsername && getState().scUsername.length > 0 && getState().scPassword && getState().scPassword.length > 0) {
            dispatch({
                type: COMMENTERSSEARCH_SUBMIT_ENABLE
          })
        } else {
            dispatch({
                type: COMMENTERSSEARCH_SUBMIT_DISABLE
          })
        }

          
    }
    
}


export function handleCommentersSearchSubmit(event) {
    
    return (dispatch, getState) => {

    dispatch({
         type: COMMENTERSSEARCH_SUBMITTED
       });
           
        axios({
            method: 'post',
            url: 'https://scbm.amfdev.co.uk/api/commentersSearch/',
            headers: {}, 
            data: {
              scUsername: getState().scUsername,
              scPassword: getState().scPassword
            }
            })
            .then(json => catchCommentersSearchScLoginError(json.data, dispatch))
            .then(json => catchCommentersSearchCookieError(json, dispatch))
            .then(json => catchCommentersSearchUserCreatedError(json, dispatch))
            .then(json => doCommentersSearchSuccess(json, dispatch))
             .catch(error => console.log(error));
                  
    }
    
}


//res.send(JSON.stringify({ commentersSearchSuccess: false, scLoginSuccess: true, scCookiesValid: true, userCreated: true, commentersSearchError: null, userData: data}));

function catchCommentersSearchScLoginError(json, dispatch) {
    console.log('catchCommentersSearchScLoginError')
    if (!json.scLoginSuccess) {
        dispatch({
                type: COMMENTERSSEARCH_SC_LOGIN_ERROR
              })
        throw Error(json.error);
    }
    
  return json;
}


function catchCommentersSearchCookieError(json, dispatch) {
    console.log('catchCommentersSearchCookieError')
    if (!json.scCookiesValid) {
        dispatch({
                type: COMMENTERSSEARCH_COOKIE_ERROR
              })
        throw Error(json.error);
    }
    
  return json;
}


function catchCommentersSearchUserCreatedError(json, dispatch) {
    console.log('catchCommentersSearchUserCreatedError')
    if (!json.userCreated) {
        dispatch({
                type: COMMENTERSSEARCH_USER_CREATED_ERROR
              })
        throw Error(json.error);
    }
    
  return json;
}


function doCommentersSearchSuccess(json, dispatch) {
    console.log('doCommentersSearchSuccess')
 
        dispatch({
                type: COMMENTERSSEARCH_SUCCESS,
                scUsername: json.userData.scUsername
              })
  return json;
}




